const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs');
(async()=>{const b=await chromium.launch();const c=await b.newContext();const p=await c.newPage();const root='http://127.0.0.1:4181';const logs=[];const log=(n,d)=>{logs.push({n,d});console.log(n,JSON.stringify(d))};await p.goto(root+'/ro/account');await p.waitForSelector('[name=email]');await p.keyboard.press('Tab');log('keyboard-first-focus',await p.locator(':focus').getAttribute('class'));
await p.locator('[name=email]').fill('client@dracula-design.com');await p.locator('[name=password]').fill(process.env.QA_PASSWORD);await p.locator('form button[type=submit]').click();await p.waitForSelector('[data-action=logout]');log('client-blocked-admin',(await p.request.get(root+'/api/admin/v1/products')).status());log('session-cookies',(await c.cookies()).map(({name,httpOnly,sameSite,secure})=>({name,httpOnly,sameSite,secure})));
await p.locator('[data-action=order]').first().click();log('order-dialog-accessibility',await p.locator('#image-dialog').evaluate(d=>({label:d.getAttribute('aria-label'),labelledby:d.getAttribute('aria-labelledby'),close:d.querySelector('button').getAttribute('aria-label')})));await p.keyboard.press('Escape');
for(const locale of ['ro','en','de']){const r=await p.request.get(root+'/api/dracula/bootstrap?lang='+locale);const j=await r.json();log('translations-'+locale,{count:j.pages.length,empty:j.pages.filter(x=>!x.body||!x.title).length,keys:Object.keys(j.ui).length});}
await p.goto(root+'/ro/collection');await p.waitForSelector('.product');await p.locator('#language').selectOption('de');await p.waitForTimeout(200);log('language-switch',{url:p.url(),lang:await p.locator('html').getAttribute('lang'),h1:await p.locator('h1').textContent()});await p.locator('#language').selectOption('ro');await p.waitForTimeout(200);
await p.locator('.product-image').first().click();await p.locator('[data-action=buy]').click();await p.waitForURL('**/checkout');log('buy-now','checkout reached');
const cookie=(await c.cookies()).find(x=>x.name==='dracula_csrf').value;const headers={'X-CSRF-Token':cookie};const payload={customer:{first_name:'QA',last_name:'Audit',email:'client@dracula-design.com',phone:'0722123456'},shipping_address:{line1:'TEST AUDIT',city:'Brasov',county:'Brasov',postal_code:'500001',country:'RO'},delivery_method:'courier',payment_method:'cash_on_delivery',accept_terms:true,expected_total_ron:0,notes:'NEGATIVE AUDIT TEST'};
for(const [name,body]of [['price-tamper',payload],['terms-false',{...payload,accept_terms:false}],['invalid-total-type',{...payload,expected_total_ron:{invalid:true}}]]){const r=await p.request.post(root+'/api/orders',{headers:{...headers,'Idempotency-Key':'audit-'+Date.now()+'-'+name},data:body});log(name,{status:r.status(),body:(await r.text()).slice(0,250)});}
log('cross-origin',(await p.request.patch(root+'/api/account/profile',{headers:{...headers,Origin:'https://not-this-store.invalid'},data:{full_name:'SHOULD NOT APPLY'}})).status());
const cart=await p.request.get(root+'/api/cart').then(r=>r.json());for(const i of cart.items)await p.request.delete(root+'/api/cart/items/'+i.product_id,{headers});log('cart-cleanup',(await p.request.get(root+'/api/cart').then(r=>r.json())).items.length);
await p.goto(root+'/ro/pages/contact');await p.waitForSelector('[name=body]');await p.locator('[name=name]').fill('QA AUDIT DESIGN');await p.locator('[name=email]').fill('qa-audit-design@example.com');await p.locator('[name=body]').fill('TEST AUDIT INDEPENDENT DESIGN - verificare salvare formular contact, nu necesita raspuns.');const rr=p.waitForResponse(r=>r.url().includes('/api/dracula/inquiry')&&r.request().method()==='POST');await p.locator('[data-form=inquiry] button').click();log('inquiry',(await rr).status());await b.close();fs.writeFileSync('work/audit-design-extra-results.json',JSON.stringify(logs,null,2));})().catch(e=>{console.error(e);process.exit(1)});
